<?php
require_once __DIR__ . '/../../includes/layout.php'; require_login(); check_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
    $sid=(int)($_POST['student_id']??0); $method=$_POST['method']??'AI Facial Recognition'; $status=$_POST['status']??'Present'; $confidence=round(mt_rand(9200,9980)/100,2);
    db()->prepare('INSERT INTO attendance(student_id,subject_id,date,status,method,confidence,marked_by) VALUES(?,?,?,?,?,?,?)')->execute([$sid,1,date('Y-m-d'),$status,$method,$confidence,$_SESSION['user_id']]);
    generate_prediction($sid); set_flash('success',"Attendance marked as $status using $method with $confidence% confidence."); redirect('attendance_ai.php');
}
$students=rows('SELECT s.*,u.full_name FROM students s JOIN users u ON u.id=s.user_id ORDER BY u.full_name');
$selected=$students[0]??null; render_header('AI Attendance');
?>
<div class="page-title"><div><h1>AI Attendance Simulation</h1><p>Facial recognition UI, QR attendance, RFID simulation and confidence score.</p></div></div>
<div class="row g-4"><div class="col-xl-7"><div class="panel"><div class="panel-title">AI Attendance (Facial Recognition)</div><div class="ai-frame"><img class="avatar-big" src="../../assets/images/default-avatar.svg"><div class="face-box"></div><div class="scan-line"></div><div class="position-absolute end-0 top-50 translate-middle-y me-3 bg-success text-white rounded-3 p-3"><strong>Match Found</strong><br><small>Confidence: <?= rand(92,99) ?>.<?= rand(10,99) ?>%</small><br><small><?= e($selected['full_name']??'Student') ?></small></div></div><form method="post" class="row g-2 mt-3"><?= csrf_field() ?><div class="col-md-5"><select name="student_id" class="form-select"><?php foreach($students as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['student_no'].' - '.$s['full_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><select name="method" class="form-select"><option>AI Facial Recognition</option><option>QR Code</option><option>RFID Simulation</option></select></div><div class="col-md-2"><select name="status" class="form-select"><option>Present</option><option>Late</option><option>Absent</option><option>Excused</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Mark</button></div></form></div></div><div class="col-xl-5"><div class="panel"><div class="panel-title">Attendance Summary</div><canvas id="summaryChart" height="180"></canvas><hr><div class="heatmap"><?php for($i=0;$i<35;$i++): ?><span></span><?php endfor; ?></div></div><div class="panel"><div class="panel-title">Recent AI Attendance</div><?php foreach(rows('SELECT a.*,u.full_name FROM attendance a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id ORDER BY a.created_at DESC LIMIT 8') as $a): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($a['full_name']) ?><br><small class="text-muted"><?= e($a['method']) ?> • <?= e($a['date']) ?></small></span><span class="badge bg-primary"><?= e($a['status']) ?></span></div><?php endforeach; ?></div></div></div>
